import{_ as a,c as i,o as t,ag as r}from"./chunks/framework.Bw-5EFTY.js";const g=JSON.parse('{"title":"What is FluentAffiliate?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started/what-is-fluentaffiliate.md","filePath":"guide/getting-started/what-is-fluentaffiliate.md","lastUpdated":1756182610000}'),o={name:"guide/getting-started/what-is-fluentaffiliate.md"};function n(l,e,s,f,u,h){return t(),i("div",null,e[0]||(e[0]=[r('<h1 id="what-is-fluentaffiliate" tabindex="-1">What is FluentAffiliate? <a class="header-anchor" href="#what-is-fluentaffiliate" aria-label="Permalink to &quot;What is FluentAffiliate?&quot;">​</a></h1><p>Welcome to <strong>FluentAffiliate</strong> your all-in-one solution for building, managing, and growing a powerful affiliate program right inside your WordPress site.</p><p>Whether you&#39;re a solo creator, eCommerce store owner, or a membership site admin, FluentAffiliate gives you the tools to turn your customers and followers into revenue-driving affiliates, with <strong>zero technical headache</strong>. Ready to get started? Check out our <a href="/guide/getting-started/installation-activation-licensing">installation and activation guide</a>.</p><h2 id="why-use-fluentaffiliate" tabindex="-1">Why Use FluentAffiliate? <a class="header-anchor" href="#why-use-fluentaffiliate" aria-label="Permalink to &quot;Why Use FluentAffiliate?&quot;">​</a></h2><p>Let&#39;s say you&#39;re selling online courses, products, or services. Now imagine if your happy customers and content creators could share your brand and <strong>earn commissions</strong> when someone buys through their links. That&#39;s affiliate marketing and FluentAffiliate makes it beautifully simple.</p><p>Here&#39;s the magic it brings:</p><ul><li><strong>Launch your own affiliate program</strong> in minutes no 3rd-party platform needed</li><li>Let users <a href="/guide/affiliate-portal/how-to-register-as-an-affiliate">sign up as affiliates</a> and track their performance</li><li>Generate <a href="/guide/affiliate-portal/generating-affiliate-links">unique referral links</a> for affiliates automatically</li><li>Track every <a href="/guide/admin-portal/managing-referrals">referral, click, and commission</a> with precision</li><li>Give both <a href="/guide/admin-portal/admin-dashboard-overview">you</a> and <a href="/guide/affiliate-portal/affiliate-dashboard-overview">your affiliates</a> detailed insights via dashboards</li><li>Manage <a href="/guide/admin-portal/payout-management">payouts</a>, <a href="/guide/settings-and-customization/email-settings">emails</a>, <a href="/guide/integrations/integrations">integrations</a>, and everything in between</li></ul><p>All of this directly from your WordPress dashboard.</p><h3 id="who-is-fluentaffiliate-for" tabindex="-1">Who Is FluentAffiliate For? <a class="header-anchor" href="#who-is-fluentaffiliate-for" aria-label="Permalink to &quot;Who Is FluentAffiliate For?&quot;">​</a></h3><p>FluentAffiliate is perfect for:</p><ul><li>Store owners using <a href="/guide/integrations/woocommerce-integration-with-fluentaffiliate">WooCommerce</a>, <a href="/guide/integrations/easy-digital-downloads-integration-with-fluentaffiliate">Easy Digital Downloads</a>, <a href="/guide/integrations/surecart-integration-with-fluentaffiliate">SureCart</a>, or similar platforms</li><li>Online course creators using <a href="/guide/integrations/learndash-integration-with-fluentaffiliate">LearnDash</a>, <a href="/guide/integrations/memberpress-integration-with-fluentaffiliate">MemberPress</a>, and more</li><li>Anyone who wants to boost sales through referral marketing</li></ul><p>No matter what you&#39;re selling, if you want to grow your business with the help of affiliates, FluentAffiliate has you covered.</p><h2 id="how-does-it-work" tabindex="-1">How Does It Work? <a class="header-anchor" href="#how-does-it-work" aria-label="Permalink to &quot;How Does It Work?&quot;">​</a></h2><p>Here&#39;s a quick peek at the flow:</p><ol><li><strong>You install Fluent Affiliate</strong> - Follow our <a href="/guide/getting-started/installation-activation-licensing">installation guide</a></li><li>You set your <a href="/guide/settings-and-customization/referral-settings">commission rules</a>, terms, and branding in the general settings.</li><li>Affiliates <a href="/guide/affiliate-portal/how-to-register-as-an-affiliate">sign up via a public registration page</a></li><li>They get a <a href="/guide/affiliate-portal/generating-affiliate-links">unique referral link</a> to share</li><li>When someone clicks &amp; buys, the affiliate earns commission which you can track in the <a href="/guide/admin-portal/managing-referrals">referrals dashboard</a></li><li>You review and send <a href="/guide/admin-portal/payout-management">payouts</a> — all from your dashboard</li></ol><p>It&#39;s simple, scalable, and built to grow with your business. Want to see all the features in detail? Check out our <a href="/guide/getting-started/fluent-affiliate-glossary">FluentAffiliate glossary</a>.</p>',16)]))}const m=a(o,[["render",n]]);export{g as __pageData,m as default};
